"""Generate server-side answer data from the same JSON files used by the UI."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
questions = json.loads((root / 'data/questions.json').read_text(encoding='utf-8'))
objects = json.loads((root / 'data/objects.json').read_text(encoding='utf-8'))['objects']
out = root / 'supabase/migration_server_answers.sql'

def q(value):
    return "'" + str(value).replace("'", "''") + "'"

lines = [
    '-- Generated by tools/build_truth_sql.py. Rebuild after editing data/*.json.',
    '-- Apply after schema.sql and migration_app_state.sql.',
    'create table if not exists public.vectra_questions (idx int primary key, answer double precision not null check (answer > 0));',
    'create table if not exists public.vectra_objects (id text primary key, size_m double precision, mass_kg double precision);',
    'alter table public.vectra_questions enable row level security;',
    'alter table public.vectra_objects enable row level security;',
    'revoke all on public.vectra_questions, public.vectra_objects from public, anon, authenticated;',
    'delete from public.vectra_questions;',
    'delete from public.vectra_objects;',
    'insert into public.vectra_questions(idx, answer) values',
    ',\n'.join(f"({i}, {repr(item['answer'])})" for i, item in enumerate(questions['questions'])) + ';',
    'insert into public.vectra_objects(id, size_m, mass_kg) values',
    ',\n'.join(f"({q(item['id'])}, {repr(item['size']['m']) if item.get('size') else 'null'}, {repr(item['mass']) if item.get('mass') else 'null'})" for item in objects) + ';',
]
out.write_text('\n'.join(lines) + '\n', encoding='utf-8')
print(out)
